from reportlab.lib.pagesizes import letter
from pypdf import PdfReader, PdfWriter
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.enums import TA_CENTER, TA_JUSTIFY
from reportlab.lib.units import inch
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.pdfbase import pdfmetrics
from reportlab.lib import colors

OUT = 'output/pdf/Disneyland_Paris_hoja_de_ruta_estrategica_traduccion_es.pdf'

pdfmetrics.registerFont(TTFont('DejaVu', r'C:\\Windows\\Fonts\\times.ttf'))
pdfmetrics.registerFont(TTFont('DejaVu-Bold', r'C:\\Windows\\Fonts\\timesbd.ttf'))
styles = getSampleStyleSheet()
body = ParagraphStyle('body', parent=styles['BodyText'], fontName='DejaVu', fontSize=10.3, leading=14, alignment=TA_JUSTIFY, spaceAfter=10)
head = ParagraphStyle('head', parent=styles['Heading1'], fontName='DejaVu-Bold', fontSize=14, leading=17, spaceBefore=14, spaceAfter=9)
sub = ParagraphStyle('sub', parent=head, fontSize=12, alignment=TA_CENTER, spaceBefore=10)
title = ParagraphStyle('title', parent=head, fontSize=20, leading=24, alignment=TA_CENTER, spaceAfter=18)
note = ParagraphStyle('note', parent=body, fontSize=8.5, leading=11, textColor=colors.HexColor('#333333'))

def P(text, style=body): return Paragraph(text, style)
def section(text): return P(text, head)
def footer(canvas, doc):
    canvas.saveState(); canvas.setFont('DejaVu', 8); canvas.setFillColor(colors.HexColor('#555555'))
    canvas.drawString(0.7*inch, 0.45*inch, 'Traducción al español - Disneyland Paris: Hoja de ruta estratégica para Europa')
    canvas.drawRightString(7.8*inch, 0.45*inch, f'Página {doc.page}')
    canvas.restoreState()

story=[]
story += [P('DISNEYLAND PARIS: DISEÑO DE UNA HOJA DE RUTA ESTRATÉGICA PARA EUROPA', title),
 P('<i>Traducción al español del caso W49948. Se han conservado los nombres propios, las denominaciones comerciales, las cifras, las fechas y las llamadas de nota del original.</i>', note), Spacer(1,8),
 P('The Walt Disney Company (Disney) se expandió a Europa con la apertura de Disneyland Paris en 1992, cerca de Marne-la-Vallée, Francia. Aunque Disney invirtió considerablemente en el parque y procuró adaptarse a las culturas locales, al principio afrontó graves dificultades financieras, baja asistencia y reacciones encontradas de los visitantes. Tras asegurar nuevas inversiones y cambiar de nombre en 1994, el parque obtuvo su primer beneficio en 1995. Desde entonces, su popularidad se disparó, convirtiéndolo en el principal destino turístico de Europa. En abril de 2025, había recibido a más de 375 millones de visitantes y contribuido de manera significativa a la economía francesa.'),
 P('Disneyland Paris atravesaba entonces una transformación de gran envergadura: la ampliación de Walt Disney Studios Park, inaugurado en 2002. Anunciada en 2018, la expansión comprendería tres nuevas áreas, centradas en <i>Marvel’s The Avengers</i>, <i>Frozen</i> y <i>The Lion King</i>. Además del desarrollo del parque temático, Disney había desempeñado un papel importante en el desarrollo de la región circundante, Val d’Europe, que se convirtió en un próspero centro urbano y comercial.'),
 P('Ahora que Disney había dejado su huella en Europa, ¿cómo debía gestionar y priorizar esta siguiente fase de crecimiento, tanto para el parque como para Val d’Europe? ¿Debía priorizar Val d’Europe para diversificar sus actividades o centrarse en el crecimiento y la ampliación del propio parque temático?'),
 section('PARQUES TEMÁTICOS DISNEY'),
 P('The Walt Disney Company era un conglomerado internacional de entretenimiento. Operaba en diversas áreas de negocio, entre ellas los parques temáticos, que ofrecían personajes de sus historias, atracciones inspiradas en el entretenimiento y opciones gastronómicas. En 1955, Disney abrió su primer parque temático en Anaheim, California. En 1983 decidió internacionalizarse y abrió un parque en Tokio, Japón, que alcanzó gran popularidad, con 125 millones de visitantes durante sus primeros diez años.'),
 P('Tras el éxito de la expansión en Tokio, Disney quiso globalizarse aún más. En 1984 elaboró una lista de 1.200 ubicaciones europeas donde podría desarrollarse un nuevo parque, incluidos países como Reino Unido, Francia, Italia y España. Dos factores decisivos fueron la accesibilidad y un clima que permitiera operar todo el año. Una vez confirmada Francia, la empresa eligió un emplazamiento cercano a Marne-la-Vallée por su proximidad a París y su ubicación central en Europa occidental. Se estimaba que unos 17 millones de europeos vivían a menos de dos horas por carretera de París, y que otros 310 millones podrían llegar a la región en menos de dos horas de vuelo.'),
 section('CONCEPCIÓN DE DISNEYLAND PARIS'), P('El plan y el proyecto', sub),
 P('Disney deseaba expandirse globalmente, y una ubicación europea ofrecía la oportunidad ideal para ampliar su presencia. Para el gobierno y las autoridades francesas, el proyecto suponía una oportunidad de crecimiento mediante infraestructura y turismo, con mayores beneficios económicos generales.'),
 P('Para operar y administrar el proyecto, Disney necesitaba una filial de propiedad íntegra que lo liderara, lo que condujo al lanzamiento de Euro Disney Associés SNC, o Euro Disney SCA. Esta era una sociedad cotizada que gestionaría el parque Disneyland Paris. Disney poseía una participación del 49 %, conforme al acuerdo que exigía que al menos el 51 % de la empresa fuera de propiedad europea.'),
 P('El acuerdo final se firmó en marzo de 1987. El proyecto fue un esfuerzo conjunto de Disney y diversas autoridades francesas, con la participación de actores clave. El acuerdo contemplaba la construcción de Disneyland Paris -entonces denominado Euro Disney- y el desarrollo general de Val d’Europe. La fase I sería un parque temático semejante a Magic Kingdom de los parques estadounidenses de Disney, además de un complejo turístico con seis hoteles y 5.200 habitaciones. La fase II se concibió como un equivalente de Disney’s Hollywood Studios en Walt Disney World Resort, Florida.'),
 P('Aunque Disney ya se había expandido internacionalmente, Europa representaba una experiencia completamente nueva. La capacidad de adaptarse a la cultura francesa local y satisfacer los gustos europeos fue un aspecto esencial. Walt Disney Imagineering Research & Development Inc. invirtió importantes recursos en el diseño del parque. Por ejemplo, el castillo situado a la entrada se adaptó a la cultura francesa y europea; su diseño se inspiró en obras medievales francesas y en los estilos de <i>Sleeping Beauty</i>, cuento fantástico y película de Disney ambientada en Alemania. Los menús y las terrazas también se ajustaron a los estándares europeos.'),
 P('Durante la construcción se desarrollaron asimismo conexiones de transporte con París mediante el Réseau Express Régional (RER), sistema ferroviario que presta servicio a París y sus suburbios. Aunque la construcción superó el presupuesto, el parque logró abrir a tiempo en 1992.'),
 section('Apertura y reacciones'),
 P('Disneyland Paris abrió el 12 de abril de 1992 bajo el nombre Euro Disney, que cambió por su denominación actual en 1994. Contaba con un parque temático principal, varios hoteles y el complejo de entretenimiento Disney. Disney había previsto unos 11 millones de visitantes en el primer año. Se esperaba que hoteles y restauración aportaran el 50 % de la facturación, y que los hoteles alcanzaran una ocupación del 85 %. Poco después de abrir, Disney entró en crisis: la asistencia, la participación y el gasto en el parque fueron muy inferiores a lo previsto. Surgieron numerosos problemas, entre ellos la salida de empleados, reacciones encontradas y confusión sobre la identidad cultural del parque: francesa, estadounidense o europea.'),
 PageBreak(), section('EVOLUCIÓN DE DISNEYLAND PARIS'),
 P('Las cuestiones financieras fueron uno de los problemas más graves. En 1993, la deuda acumulada ascendía aproximadamente a 3.800 millones de dólares estadounidenses, y Euro Disney SCA afrontaba además crecientes cargas financieras y pérdidas. En 1994 inició una refinanciación y negoció con el príncipe y multimillonario saudí Alwaleed bin Talal, quien invirtió una participación del 24 % en Euro Disney SCA. Ese mismo año el parque pasó oficialmente de Euro Disney a Disneyland Resort Paris, para eliminar las connotaciones de dinero y comercio asociadas al nombre original.'),
 P('En 1995 la situación comenzó a mejorar. Disney inauguró Space Mountain con una celebración de apertura que contó con celebridades. Ese año, el parque registró su primer beneficio trimestral: 35,2 millones de dólares. En 2002 abrió la segunda fase del proyecto, Walt Disney Studios Park.'),
 P('Aunque Disneyland Paris experimentó altibajos, a partir de 2005 obtuvo en general beneficios y mejor crecimiento. Durante la década de 2010, el parque creció aún más y alcanzó varios hitos. En 2010, Disney firmó un acuerdo para ampliar el desarrollo del parque temático y la región de Val d’Europe hasta 2030. En 2011, el número total de asistentes alcanzó los 250 millones. En 2015 comenzaron importantes renovaciones para preparar el 25.º aniversario en 2017. Ese año, Disney recompró todas las acciones de la filial europea Euro Disney SCA, que pasó a estar íntegramente bajo propiedad de Disney.'),
 P('El año 2018 también fue significativo. Bob Iger, director ejecutivo de Disney, anunció un plan de desarrollo de 2.000 millones de euros para los años siguientes. El desarrollo se centraría en Walt Disney Studios Park e introduciría tres nuevos mundos. En 2020, Disney y las autoridades locales firmaron otra prórroga del acuerdo de 1987, vigente hasta 2040, para incluir el desarrollo de Disney y de Val d’Europe.'),
 P('En 2023, Disneyland Paris logró un beneficio operativo récord de 188,5 millones de dólares (175 millones de euros), tras aumentar sus ingresos un 23,5 % hasta un máximo histórico de 3.100 millones de dólares (2.900 millones de euros). Esta cifra representó el 56,4 % de los ingresos internacionales generados por la división de parques y experiencias de Disney y el 17,1 % de su beneficio. En 2024, los World Travel Awards nombraron a Disneyland Paris el mejor complejo de parques temáticos de Europa. Desde su apertura había recibido más de 375 millones de visitantes; en 2025 incluía los dos parques temáticos originales, siete hoteles Disney tematizados, Disney Village y un espacio integrado para eventos corporativos. Desde 1992 había aportado más de 84.500 millones de euros de valor a la economía francesa, contribuido a decenas de miles de puestos de trabajo y representado el 6 % de los ingresos turísticos del país.'),
 section('DESARROLLO Y AMPLIACIÓN DE WALT DISNEY STUDIOS'),
 P('La iniciativa más reciente era la ampliación de Walt Disney Studios Park, inaugurado en 2002. Tras completarse las zonas temáticas de <i>Frozen</i>, el parque pasaría a llamarse Disney Adventure World.'),
 P('Una parte principal de la fase III fue la ampliación de Marvel Avengers Campus, inaugurado en julio de 2022 durante las celebraciones del 30.º aniversario. Basado en la célebre serie cinematográfica de Marvel Avengers, permitía a los visitantes convertirse en reclutas y entrenar junto a superhéroes. El área incluía atracciones, entretenimiento y opciones gastronómicas temáticas, además de tecnología avanzada para Disneyland Paris, como reconocimiento gestual, fotografías dinámicas de imagen congelada y el primer animatrónico de Avengers en un parque Disney.'),
 P('A partir de las lecciones de la construcción inicial, los Imagineers prestaron especial atención a los detalles. Como señaló el Imagineer Jim Shull en <i>Forbes</i>: «Las fábricas europeas no se parecen a las estadounidenses; las instalaciones eléctricas, los accesorios y las paredes son diferentes». Esos detalles se tuvieron en cuenta al diseñar las fábricas del Avengers Campus. Otra parte importante de la renovación Marvel fue la remodelación integral del Disney Hotel New York, que reabrió en 2021 con arte de Marvel, decoración neoyorquina y opciones gastronómicas temáticas.'),
 PageBreak(), section('World of Frozen'),
 P('Otra parte importante de la fase III era World of Frozen, basado en la exitosa película animada <i>Frozen</i> (2013). Se esperaba que abriera en 2026 e incluyera una montaña North Mountain de 36 metros para recrear el palacio de hielo de Elsa. Otros elementos serían la atracción acuática Frozen Ever After y una inmersiva aldea de Arendelle, con restaurante, tiendas y encuentros con personajes. Una de las partes más ambiciosas era un lago artificial, Adventure Bay, que acogería un espectáculo nocturno de agua con drones y fuentes.'),
 section('Pride Lands'),
 P('La zona Pride Lands era uno de los mayores desarrollos de la ampliación. Sería la primera tierra inmersiva de <i>The Lion King</i> construida en el mundo y exclusiva de Disneyland Paris. Incluiría una réplica de Pride Rock y un recorrido por los paisajes de la película, con personajes y banda sonora. Pride Rock contaría con una atracción acuática de troncos, además de restauración temática y experiencias con personajes. Se esperaba que fuera una de las experiencias Disney más avanzadas, con efectos especiales de última generación y los característicos audio-animatrónicos de Disney para dar vida a <i>The Lion King</i>.'),
 section('Otros desarrollos'),
 P('Como parte de la modernización continua, varios hoteles y alojamientos serían renovados. Sequoia Lodge, inspirado en parques nacionales estadounidenses, recibiría una amplia renovación en 2026. También se preveía una gran renovación de Davy Crockett Ranch, con 584 bungalós actualizados bajo una nueva temática.'),
 P('Además de la construcción de los tres mundos y de las mejoras hoteleras, Disney ampliaba otras áreas. Adventure Way sería una zona cercana a Disney Adventure Land e incluiría un carrusel inspirado en <i>Up</i> de Pixar y Disney, y jardines temáticos inspirados en <i>Tangled</i> de Disney y <i>Toy Story</i> de Pixar. Disney Village también experimentaría una transformación importante para modernizar sus opciones comerciales y de entretenimiento. Desde enero de 2025, Disneyland Paris incorporó un espectáculo nocturno de tecnología avanzada que, por primera vez en el parque, incluyó Main Street como parte del espectáculo.'),
 section('VAL D’EUROPE'),
 P('El acuerdo de 1987 incluía la construcción del parque Disney y el desarrollo general de Val d’Europe. La idea era contribuir al reequilibrio del desarrollo de la región de Île-de-France. Junto con Disneyland Paris, esta región se había convertido en un próspero espacio empresarial y residencial. El equipo de Real Estate Development by Euro Disney supervisaba el turismo y el desarrollo urbano de Val d’Europe.'),
 P('Val d’Europe reunía centros comerciales de lujo, zonas residenciales y áreas de negocios, formando una dinámica comunidad urbana próxima a Disneyland Paris. Contaba con buenas conexiones de transporte y albergaba el principal nodo de TGV de Francia, que conectaba Val d’Europe con grandes ciudades francesas y europeas en menos de tres horas. Desde que empezó a desarrollarse en la década de 1980, su población se había multiplicado por siete. Disney y las autoridades francesas atribuyeron el crecimiento y el éxito a su alianza y esfuerzo sostenidos.'),
 P('La región atrajo residentes y grandes empresas, y recibió numerosos reconocimientos. Multinacionales como Deloitte y Tesla Inc. eligieron Val d’Europe para sus oficinas. En marzo de 2025, la tasa de desempleo era del 6,8 %, inferior a la de París y Francia; el ingreso medio por hogar era de 26.000 euros anuales, superior al de la capital nacional.'),
 P('Las partes involucradas firmaron recientemente un acuerdo para desarrollar más la zona y fijar objetivos entre 2025 y 2040: 112.000 metros cuadrados de oficinas, 90.000 metros cuadrados de espacio por definir, más viviendas y habitaciones de hotel, y la meta de alcanzar 80.000 habitantes y empleos en 2040.'),
 section('PERSPECTIVAS FUTURAS'),
 P('Aunque Disneyland Paris tuvo un comienzo difícil, atravesó una inmensa transformación hasta convertirse en el principal destino turístico de Europa y alcanzar sus objetivos iniciales. Después de más de 33 años difundiendo la magia Disney en Europa, había reproducido el éxito de sus demás parques en el mundo.'),
 P('Su éxito y las inversiones recientes y en curso indicaban que Disney no planeaba detenerse y continuaría expandiéndose mediante la fase III. ¿Cómo debía gestionar y priorizar esta nueva fase de crecimiento, tanto para el parque como para Val d’Europe? A la luz de los desafíos iniciales, ¿qué debía considerar al seguir desarrollando ambos ámbitos? Aunque Disney ya había dejado su huella en Europa, convenía analizar cómo podría crecer más. Disney no se había caracterizado tradicionalmente por sus actividades inmobiliarias, pero el éxito y el impresionante crecimiento de Val d’Europe demostraban su potencial. ¿Debía Disney priorizar Val d’Europe para diversificar su negocio o centrarse en el crecimiento y la ampliación del propio parque temático?'),
 section('NOTAS FINALES Y FUENTES'),
 P('Las llamadas de nota del documento original corresponden a 44 fuentes publicadas, entre ellas comunicados de Disney, artículos periodísticos, publicaciones académicas y páginas institucionales. Para preservar la trazabilidad bibliográfica, las referencias se mantienen en su idioma de publicación, sin alterar autores, títulos, fechas, enlaces ni identificadores. Las dos páginas de referencias originales se incorporan al final de este archivo.', note),
 P('Principales fuentes citadas: The Walt Disney Company, Disneyland Paris News, Harvard Magazine, Los Angeles Times, The New York Times, Forbes, Journal of Tourism Studies, International Directory of Company Histories, Encyclopedia.com y Legislative Council Secretariat. Las referencias completas, incluidas sus URL, constan en las páginas 6 y 7 del documento de origen.', note),
 P('<i>Nota sobre la traducción:</i> este documento constituye una traducción de trabajo de alta fidelidad. No incorpora certificación, sello ni declaración jurada de traductor oficial.', note)]

doc=SimpleDocTemplate(OUT, pagesize=letter, rightMargin=.72*inch, leftMargin=.72*inch, topMargin=.72*inch, bottomMargin=.68*inch)
doc.build(story, onFirstPage=footer, onLaterPages=footer)
translated = PdfReader(OUT)
source = PdfReader(r'C:\\Users\\angel\\Downloads\\dddda6d0-1c68-488e-8582-1c70335c0e3b.pdf')
writer = PdfWriter()
for page in translated.pages: writer.add_page(page)
for page in source.pages[5:7]: writer.add_page(page)
with open(OUT, 'wb') as f: writer.write(f)
